mapper.select:
SELECT b.id FROM expert_review_batch b LEFT JOIN workflow_node_config n ON n.id=b.workflow_node_id
    WHERE b.module_instance_id=#{module} AND b.round_no=#{round} AND b.access_ended_at IS NULL
    AND REPLACE(REPLACE(n.node_id,'ExpertAssignTask','ExpertReviewTask'),'ExpertSummaryTask','ExpertReviewTask')=#{node}
